alter table public.facebook_rotation_settings add column if not exists paused_connection_keys text[] not null default '{}'; alter table public.facebook_rotation_settings add column if not exists last_generated_week text; alter table public.facebook_rotation_settings add column if not exists last_generated_at timestamptz;
create or replace function public.facebook_rotation_generate_week(target_date date default ((now() at time zone 'Asia/Bangkok')::date)) returns integer language plpgsql security definer set search_path=public as $$
declare wk text; monday date; inserted_count integer:=0; page_key text; p record; rn integer; rot integer; day_offset integer; slot integer; local_ts timestamp; page_shift integer; begin monday:=target_date-(extract(isodow from target_date)::int-1); wk:=to_char(monday,'IYYY-IW'); if exists(select 1 from public.facebook_rotation_queue where week_key=wk) then return 0; end if; for page_key in select unnest(active_connection_keys) from public.facebook_rotation_settings where id=true loop page_shift:=case when page_key='page_1' then 0 else 10 end; rn:=0; for p in select id from public.products where status in ('ready_to_list','published','reserved') order by id loop for rot in 1..2 loop day_offset:=(rn % 7); slot:=((rn/7)::int % 12); local_ts:=monday::timestamp+day_offset*interval '1 day'+case when slot<5 then time '11:30'+slot*interval '25 minutes' else time '18:30'+(slot-5)*interval '25 minutes' end+page_shift*interval '1 minute'; insert into public.facebook_rotation_queue(product_id,connection_key,scheduled_at,week_key,rotation_no,template_id,status) values(p.id,page_key,local_ts at time zone 'Asia/Bangkok',wk,rot,'ROT-'||(((rn+rot-1)%8)+1),'PLANNED') on conflict do nothing; if found then inserted_count:=inserted_count+1; end if; rn:=rn+1; end loop; end loop; end loop; update public.facebook_rotation_settings set last_generated_week=wk,last_generated_at=now() where id=true; return inserted_count; end $$; revoke all on function public.facebook_rotation_generate_week(date) from public,anon,authenticated; grant execute on function public.facebook_rotation_generate_week(date) to service_role;